<script setup>import{Head,Link,router,usePage}from'@inertiajs/vue3';import{ref}from'vue';import Flash from'../Components/Flash.vue';const open=ref(false),page=usePage();const links=[['Dashboard','/admin'],['Products','/admin/products'],['Services','/admin/services'],['Carousel','/admin/carousel'],['Reels','/admin/reels'],['Categories & brands','/admin/catalog'],['Orders','/admin/orders'],['Service requests','/admin/inquiries'],['Google Merchant','/admin/merchant']];const active=u=>u==='/admin'?page.url==='/admin':page.url.startsWith(u);</script><template><div class="min-h-screen bg-slate-100"><Head><meta head-key="robots" name="robots" content="noindex,nofollow"></Head><Flash/><aside class="fixed inset-y-0 left-0 hidden w-64 bg-slate-950 p-4 lg:block"><img src="/assets/prinx-logo.svg" class="h-10 brightness-0 invert"><nav class="mt-8 grid gap-1"><Link v-for="l in links" :key="l[1]" :href="l[1]" :class="['rounded-[9px] px-3 py-2.5 text-sm font-bold',active(l[1])?'bg-prinx-500 text-white':'text-slate-300 hover:bg-slate-900']">{{l[0]}}</Link></nav><Link href="/" class="absolute bottom-5 left-4 right-4 rounded-[9px] border border-slate-700 px-3 py-2 text-center text-sm font-bold text-white">View store</Link></aside><div class="lg:pl-64"><header class="sticky top-0 z-30 flex h-16 items-center justify-between border-b bg-white px-4 lg:px-8"><div><p class="text-xs font-black uppercase tracking-wider text-prinx-600">Administration</p><p class="font-black">Prinx Electronics</p></div><div class="flex items-center gap-3"><span class="hidden text-sm font-bold sm:block">{{page.props.auth.user?.name}}</span><button class="text-sm font-bold text-slate-500" @click="router.post('/logout')">Sign out</button></div></header><main class="p-4 lg:p-8"><slot/></main></div></div></template>
